import csv
import json

# Define a function to compute revenue
def compute_revenue(order):
    return float(order['units']) * float(order['unit_price'])

# Read the CSV file
with open('orders.csv', mode='r') as csv_file:
    csv_reader = csv.DictReader(csv_file)
    orders = list(csv_reader)

# Filter orders by status and compute revenue per region
revenue_per_region = {}
for order in orders:
    if order['status'] in ['completed', 'refunded']:
        region = order['region']
        revenue = compute_revenue(order)
        if region in revenue_per_region:
            revenue_per_region[region] += revenue
        else:
            revenue_per_region[region] = revenue

# Round revenue to 2 decimal places and convert to JSON
revenue_per_region = {region: round(revenue, 2) for region, revenue in revenue_per_region.items()}

# Print the result
print(json.dumps(revenue_per_region))
